{"file_path":"src/pointer.js","content":"/** JSON Pointer parsing, formatting and resolution over JSON data. */

/** Failure raised while parsing or resolving a pointer. */
export class PointerError extends Error {
  /**
   * @param {string} message reason, including the pointer position when known
   * @param {unknown} [pointer] the pointer the failure came from
   */
  constructor(message, pointer) {
    super(message);
    this.name = 'PointerError';
    this.pointer = pointer;
  }
}

const INDEX_PATTERN = /^(0|[1-9][0-9]*)$/;

/**
 * Decode a single reference token, resolving `~1` and `~0` escapes left to
 * right in one pass.
 *
 * @param {string} token raw (still-escaped) token text
 * @param {string} pointer the whole pointer, for error reporting
 * @returns {string} the decoded token
 */
function decodeToken(token, pointer) {
  let result = '';
  let i = 0;
  while (i < token.length) {
    const c = token[i];
    if (c === '~') {
      const next = token[i + 1];
      if (next === '0') {
        result += '~';
        i += 2;
      } else if (next === '1') {
        result += '/';
        i += 2;
      } else {
        const sequence = next === undefined ? '~' : `~${next}`;
        throw new PointerError(`invalid escape in pointer token: ${sequence}`, pointer);
      }
    } else {
      result += c;
      i += 1;
    }
  }
  return result;
}

/**
 * Encode a single reference token, escaping `~` before `/`.
 *
 * @param {string} token decoded token text
 * @returns {string} the escaped token
 */
function encodeToken(token) {
  return token.split('~').join('~0').split('/').join('~1');
}

/**
 * Split a pointer into decoded reference tokens.
 *
 * @param {string} pointer JSON Pointer text
 * @returns {string[]} the decoded tokens, empty for the whole-document pointer
 */
export function parsePointer(pointer) {
  if (typeof pointer !== 'string') {
    throw new PointerError('pointer must be a string', pointer);
  }
  if (pointer === '') return [];
  if (pointer[0] !== '/') {
    throw new PointerError("pointer must be empty or start with '/'", pointer);
  }
  const rawTokens = pointer.slice(1).split('/');
  return rawTokens.map((token) => decodeToken(token, pointer));
}

/**
 * Join reference tokens into a pointer.
 *
 * @param {string[]} tokens reference tokens
 * @returns {string} the pointer text, empty for no tokens
 */
export function formatPointer(tokens) {
  if (!Array.isArray(tokens)) {
    throw new PointerError('tokens must be an array');
  }
  for (const token of tokens) {
    if (typeof token !== 'string') {
      throw new PointerError('reference token must be a string');
    }
  }
  return tokens.map((token) => `/${encodeToken(token)}`).join('');
}

/**
 * Resolve a pointer against a document.
 *
 * @param {unknown} document JSON data to walk
 * @param {string} pointer JSON Pointer text
 * @returns {unknown} the value the pointer selects
 */
export function resolve(document, pointer) {
  if (pointer === '') return document;
  const tokens = parsePointer(pointer);
  let current = document;
  for (let i = 0; i < tokens.length; i += 1) {
    const token = tokens[i];
    const traversed = formatPointer(tokens.slice(0, i + 1));
    if (Array.isArray(current)) {
      if (!INDEX_PATTERN.test(token)) {
        throw new PointerError(`invalid array index: ${token} at ${traversed}`, pointer);
      }
      const index = Number(token);
      if (index >= current.length) {
        throw new PointerError(`index out of range: ${token} at ${traversed}`, pointer);
      }
      current = current[index];
    } else if (current !== null && typeof current === 'object') {
      if (!Object.prototype.hasOwnProperty.call(current, token)) {
        throw new PointerError(`missing property: ${token} at ${traversed}`, pointer);
      }
      current = current[token];
    } else {
      const typeName = current === null ? 'null' : typeof current;
      throw new PointerError(`cannot index into ${typeName} at ${traversed}`, pointer);
    }
  }
  return current;
}

export { INDEX_PATTERN };
"}

